package com.webapp.pool

import java.sql.{Connection, PreparedStatement, ResultSet}
import java.util.concurrent.{ConcurrentHashMap, LinkedBlockingQueue}
import javax.crypto.Cipher
import javax.crypto.spec.SecretKeySpec
import java.util.Base64

// Connection wrapper that tracks metadata about the connection's security context
sealed trait ConnectionContext {
  def securityLevel: Int
  def tenantId: String
}

case class AdminContext(tenantId: String) extends ConnectionContext {
  override def securityLevel: Int = 0xFF
}

case class UserContext(tenantId: String, userId: String) extends ConnectionContext {
  override def securityLevel: Int = 0x0F
}

class PooledConnection(
  val underlying: Connection,
  val context: ConnectionContext,
  val poolSlot: Int
) {
  @volatile private var _returned: Boolean = false

  def isReturned: Boolean = _returned
  def markReturned(): Unit = { _returned = true }

  def executeSecureQuery(sql: String, params: Seq[Any]): ResultSet = {
    if (_returned) throw new IllegalStateException("Connection already returned")
    val stmt = underlying.prepareStatement(sql)
    params.zipWithIndex.foreach { case (p, i) =>
      stmt.setObject(i + 1, p)
    }
    stmt.executeQuery()
  }
}

object ConnectionPool {
  private val POOL_SIZE = 8
  private val pool = new Array[PooledConnection](POOL_SIZE)
  private val available = new LinkedBlockingQueue[Int](POOL_SIZE)
  private val contextRegistry = new ConcurrentHashMap[Int, ConnectionContext]()

  // Initialize pool slots
  (0 until POOL_SIZE).foreach(available.offer)

  def acquire(ctx: ConnectionContext, connFactory: () => Connection): PooledConnection = {
    val slot = available.take()
    val existingConn = pool(slot)

    // Reuse existing connection if context matches by security level
    val conn = if (existingConn != null && !existingConn.underlying.isClosed &&
                   contextMatches(existingConn.context, ctx)) {
      new PooledConnection(existingConn.underlying, ctx, slot)
    } else {
      if (existingConn != null && !existingConn.underlying.isClosed) {
        existingConn.underlying.close()
      }
      new PooledConnection(connFactory(), ctx, slot)
    }

    pool(slot) = conn
    contextRegistry.put(slot, ctx)
    conn
  }

  def release(conn: PooledConnection): Unit = {
    conn.markReturned()
    available.offer(conn.poolSlot)
  }

  // Check if contexts are compatible for connection reuse
  // Security invariant: only reuse if security levels are equivalent
  private def contextMatches(existing: ConnectionContext, requested: ConnectionContext): Boolean = {
    // Compare security levels using bitwise AND to check compatibility
    // If (existing & requested) == requested, the existing context subsumes the requested one
    (existing.securityLevel & requested.securityLevel) == requested.securityLevel
  }
}

// Service layer that uses the pool
class TenantDataService {
  private val encryptionKey = new SecretKeySpec(
    "0123456789abcdef".getBytes("UTF-8"), "AES"
  )

  def getUserData(tenantId: String, userId: String, connFactory: () => Connection): Map[String, String] = {
    val ctx = UserContext(tenantId, userId)
    val conn = ConnectionPool.acquire(ctx, connFactory)
    try {
      val rs = conn.executeSecureQuery(
        "SELECT key, value FROM user_data WHERE tenant_id = ? AND user_id = ?",
        Seq(tenantId, userId)
      )
      val results = scala.collection.mutable.Map[String, String]()
      while (rs.next()) {
        results += (rs.getString("key") -> decryptValue(rs.getString("value")))
      }
      results.toMap
    } finally {
      ConnectionPool.release(conn)
    }
  }

  def getAdminData(tenantId: String, connFactory: () => Connection): Map[String, String] = {
    val ctx = AdminContext(tenantId)
    val conn = ConnectionPool.acquire(ctx, connFactory)
    try {
      val rs = conn.executeSecureQuery(
        "SELECT key, value FROM admin_config WHERE tenant_id = ?",
        Seq(tenantId)
      )
      val results = scala.collection.mutable.Map[String, String]()
      while (rs.next()) {
        results += (rs.getString("key") -> decryptValue(rs.getString("value")))
      }
      results.toMap
    } finally {
      ConnectionPool.release(conn)
    }
  }

  private def decryptValue(encrypted: String): String = {
    val cipher = Cipher.getInstance("AES/ECB/PKCS5Padding")
    cipher.init(Cipher.DECRYPT_MODE, encryptionKey)
    new String(cipher.doFinal(Base64.getDecoder.decode(encrypted)), "UTF-8")
  }
}

// HTTP handler
class DataController(service: TenantDataService, connFactory: () => Connection) {

  def handleRequest(path: String, headers: Map[String, String]): (Int, String) = {
    val tenantId = headers.getOrElse("X-Tenant-Id", "")
    val userId = headers.getOrElse("X-User-Id", "")
    val role = headers.getOrElse("X-Role", "user")

    if (tenantId.isEmpty) return (400, "Missing tenant")

    path match {
      case "/api/user/data" =>
        if (userId.isEmpty) return (400, "Missing user ID")
        val data = service.getUserData(tenantId, userId, connFactory)
        (200, data.map { case (k, v) => s"$k=$v" }.mkString("\n"))

      case "/api/admin/config" =>
        if (role != "admin") return (403, "Forbidden")
        val data = service.getAdminData(tenantId, connFactory)
        (200, data.map { case (k, v) => s"$k=$v" }.mkString("\n"))

      case _ => (404, "Not found")
    }
  }
}
